#include "decode.hpp"
#include <cstdio>
#include <cstring>
#include <vector>
using namespace halo6000;
static bool ok(Status s){if(s.ok())return true;fprintf(stderr,"%s\n",s.error().message.c_str());return false;}
static std::vector<uint32_t>read(const void*p,size_t n){std::vector<uint32_t>v(n);if(!ok(cuda_status(cudaMemcpy(v.data(),p,n*4,cudaMemcpyDeviceToHost),"signed layer copy")))exit(2);return v;}
struct Frame{std::vector<uint32_t>hidden,state,conv,routes;};
static size_t different(const std::vector<uint32_t>&a,const std::vector<uint32_t>&b){size_t n=0;for(size_t i=0;i<a.size();i++)n+=a[i]!=b[i];return n;}
int main(int argc,char**argv){if(argc!=3)return 2;auto image=load_cached(argv[1],argv[2]);if(!image.ok())return 2;auto made=DeviceModel::create(image.value(),1,32);if(!made.ok())return 2;auto m=std::move(made.value());if(!m->has_rotation)return 3;int signs=0,b128=0,b256=0;for(auto&l:m->weights.layer){for(auto*v:{&l.output,&l.expert_down,&l.shared_down}){if(!(v->flags&RotationEnabled)||!v->aux)return 3;int b=rotation_block(v->flags);if(b==128)b128++;else if(b==256)b256++;else return 3;auto values=read(v->aux,v->k);for(auto bits:values)if(bits!=0x3f800000&&bits!=0xbf800000)return 3;signs++;}}if(signs!=120||b128!=110||b256!=10)return 3;
 auto made_w=Workspace::create(32);if(!made_w.ok())return 2;auto w=std::move(made_w.value());size_t total=0;int layers=0;
 for(int l=0;l<Layers;l++){if(attention_layer(l))continue;std::vector<Frame>reference;size_t bad=0;for(int path=0;path<2;path++){if(!ok(m->reset()))return 2;for(int p=0;p<4;p++){if(!ok(embed(*m,w->view,100+p*31)))return 2;if(path){if(!ok(run_gdn_layer(*m,w->view,l,0,188)))return 2;}else for(int phase=0;phase<=int(LayerPhase::Down);phase++)if(!ok(run_gdn_phase(*m,w->view,l,0,LayerPhase(phase),188)))return 2;Frame f{read(w->view.hidden,Hidden),read(m->state.gdn+size_t(linear_index(l))*ValueHeads*ValueDim*StateDim,size_t(ValueHeads)*ValueDim*StateDim),read(m->state.conv+size_t(linear_index(l))*ConvChannels*(ConvTaps-1),size_t(ConvChannels)*(ConvTaps-1)),read(w->view.route_ids,TopExperts)};if(!path)reference.push_back(std::move(f));else bad+=different(reference[p].hidden,f.hidden)+different(reference[p].state,f.state)+different(reference[p].conv,f.conv)+different(reference[p].routes,f.routes);}}total+=bad;layers++;printf("{\"guard\":\"actual_signed_GDN_control_vs_coarse\",\"layer\":%d,\"steps\":4,\"bit_errors\":%zu}\n",l,bad);if(bad)return 1;}
 struct TokenFrame{std::vector<uint32_t>logits,state,conv,key,value,position;};std::vector<TokenFrame>tokens;
 for(int lanes:{32,16,8}){m->matvec_lanes=lanes;if(!ok(m->reset()))return 2;size_t bad=0;for(int p=0;p<4;p++){if(!ok(run_token(*m,w->view,100+p*31,p,0,188)))return 2;size_t kv=size_t(AttentionLayers)*32*KVHeads*HeadDim/2;TokenFrame f{read(w->view.logits,Vocab),read(m->state.gdn,GdnFloatsPerSlot),read(m->state.conv,ConvFloatsPerSlot),read(m->state.key,kv),read(m->state.value,kv),read(m->state.positions,1)};if(lanes==32)tokens.push_back(std::move(f));else{const auto&r=tokens[p];bad+=different(r.logits,f.logits)+different(r.state,f.state)+different(r.conv,f.conv)+different(r.key,f.key)+different(r.value,f.value)+different(r.position,f.position);}}printf("{\"guard\":\"actual_signed_whole_token_row_mapping\",\"row_lanes\":%d,\"steps\":4,\"bit_errors\":%zu}\n",lanes,bad);total+=bad;if(bad)return 1;}
 printf("{\"signed_vectors\":%d,\"block128\":%d,\"block256\":%d,\"GDN_layers_guarded\":%d,\"steps_per_layer\":4,\"bit_errors\":%zu,\"scope\":\"actual signed artifact phase placement and whole-row mapping; not whole-model fork equivalence\"}\n",signs,b128,b256,layers,total);return total?1:0;
}
